// Senior operations, lifecycle change, automation, and capstone lessons.
const P = (label, command, actor, target, pre, expected, verify, rollback, lang='bash') => ({label,command,actor,target,pre,expected,verify,rollback,lang});
const L = x => ({
  ...x,
  quick: x.quick || `Use this lesson to make a bounded decision about ${x.scope.slice(0,3).join(', ')}. Confirm target, authority, state, and recovery boundary before changing anything.`,
  first: 'Capture the exact target, release, role, timestamp, and read-only state before acting.',
  concept: `Follow ${x.scope.join('; ')} across the service boundary. Each stage has its own owner and evidence; a successful command is not proof of the business outcome.`,
  model: `Decision path: ${x.scope.join(' → ')}. The arrows are dependencies to verify, not proof of causality.`,
  stopRule: 'Stop if target identity, role, authority, prerequisites, data-loss decision, or rollback path is uncertain; preserve evidence and escalate.',
  checks: ['Compare pre-state and post-state from independent evidence.', 'Validate the affected application or business transaction, not only the Db2 return code.'],
  checklist: ['Name the host, instance, database, member, and role.', 'Capture baseline and confirm prerequisites.', 'Choose the supported and least disruptive branch.', 'Verify state and service behavior independently.', 'Record evidence, owner, and recovery boundary.']
});
const R = {
 fixpack:['IBM installFixPack','https://www.ibm.com/docs/en/db2/12.1.x?topic=commands-installfixpack-update-installed-db2-database-products'],
 upgrade:['IBM UPGRADE DATABASE','https://www.ibm.com/docs/en/db2/12.1.x?topic=commands-upgrade-database'],
 ready:['IBM database upgrade readiness check','https://www.ibm.com/docs/en/db2/12.1?topic=tasks-verifying-that-your-databases-are-ready-upgrade'],
 restr:['IBM Db2 upgrade restrictions','https://www.ibm.com/docs/en/db2/12.1.x?topic=servers-upgrade-restrictions'],
 backup:['IBM BACKUP DATABASE','https://www.ibm.com/docs/en/db2/12.1.x?topic=commands-backup-database'],
 restore:['IBM RESTORE DATABASE','https://www.ibm.com/docs/en/db2/12.1.x?topic=commands-restore-database'],
 roll:['IBM rollforward recovery','https://www.ibm.com/docs/en/db2/12.1.x?topic=recover-rollforward-recovery'],
 recover:['IBM RECOVER DATABASE','https://www.ibm.com/docs/en/db2/12.1.x?topic=commands-recover-database'],
 export:['IBM EXPORT','https://www.ibm.com/docs/en/db2/12.1.x?topic=commands-export'],
 load:['IBM LOAD overview','https://www.ibm.com/docs/en/db2/12.1.x?topic=utility-load-overview'],
 move:['IBM db2move','https://www.ibm.com/docs/en/db2/12.1.x?topic=commands-db2move-database-movement-tool'],
 cross:['IBM cross-platform backup and restore','https://www.ibm.com/docs/en/db2/12.1.x?topic=dbrs-backup-restore-operations-between-different-operating-systems-hardware-platforms'],
 monitor:['IBM monitoring interfaces','https://www.ibm.com/docs/en/db2/12.1.x?topic=monitoring-interfaces-database'],
 mon:['IBM MON routines','https://www.ibm.com/docs/en/db2/12.1.x?topic=functions-monitor-mon-routines'],
 diag:['IBM diagnostic log interpretation','https://www.ibm.com/docs/en/db2/12.1.x?topic=files-interpreting-diagnostic-log-file-entries'],
 hadr:['IBM HADR configuration','https://www.ibm.com/docs/en/db2/12.1.x?topic=hadr-database-configuration'],
 takeover:['IBM TAKEOVER HADR','https://www.ibm.com/docs/en/db2/12.1.x?topic=commands-takeover-hadr'],
 tls:['IBM configure TLS','https://www.ibm.com/docs/en/db2/12.1?topic=ctcsc-configure-tls-db2-server'],
 encryption:['IBM Db2 native encryption','https://www.ibm.com/docs/en/db2/12.1.x?topic=rest-db2-native-encryption'],
 auth:['IBM Db2 12.1 changed authority behavior','https://www.ibm.com/docs/en/db2/12.1.x?topic=121-changed-functionality']
};
export const makeLesson = ({id,title,scope,branches,steps,pre,commands,example,expected,issues,lab,q,a,diagram,refs,related}) => L({
  id,title,scope,branches,lifecycle:steps,precheck:pre,commands:commands.map(c=>P(...c)),example,expected,
  issues:issues.map(i=>({symptom:i[0],evidence:i[1],cause:i[2],fix:i[3],avoid:i[4]})),
  lab,question:q,answer:a,diagram,refs,related
});
const M = makeLesson;

export const lessons = [
M({id:'I-01',title:'Db2 maintenance and fix-pack changes',scope:['install copy and instance inventory','fix-pack installation method','online/offline restrictions','binary update versus database format change','post-update validation'],branches:[['In-place update','Use the documented installer method for the existing copy and topology.','A successful installer does not prove each instance is ready.'],['Out-of-place update','Install a second copy and switch instances under a tested plan.','Requires disk, client, and rollback planning.'],['Database format upgrade','Treat UPGRADE DATABASE as a separate, explicit change.','Replacing binaries does not reverse a database upgrade.']],steps:['Inventory copies, instances, databases, clients, topology, and add-ons.','Check target fix-pack prerequisites and supported install method.','Verify recovery copy, compatibility, space, packages, and outage plan.','Rehearse on a clone; record before/after levels and rollback boundary.','Update binaries; separately execute any approved database upgrade.','Validate connections, critical transactions, backup, restore, and HA.'],pre:['Record db2level, db2ls, db2licm -l, instance and database inventory.','Identify all instances using this copy and topology-specific restrictions.','Verify a recent recoverable backup and documented installer recovery path.'],commands:[['Inventory code','db2level; db2ls; db2licm -l','Instance owner / host operator','Selected install copy and instance','Run under the intended Db2 profile; save pre-change evidence.','Current code, installation path, and registered products are displayed.','Reconcile every instance and product with the change manifest.','Read-only.'],['Illustrative update','./installFixPack -b /opt/ibm/db2/V12.1','Privileged installer','One approved Db2 install copy','Read target README and exact flags; confirm free space, method, instance scope, backups, and outage approval.','Installer completes with a successful summary.','Run db2level per instance and test applications, backup, restore, and HA.','Follow the documented method-specific recovery; do not assume binary rollback undoes a database UPGRADE.']],example:'Track target binary level and database format as separate change items. A fix pack can update the copy while a database still requires a planned upgrade.',expected:'The change record names source/target levels, method, affected instances, database-upgrade decision, validation, and tested recovery boundary.',issues:[['Instance will not start','installer logs, db2level, environment path, instance-update status, db2diag','wrong copy, incomplete instance update, or missing OS prerequisite','stop traffic, preserve logs, and follow the exact installer recovery procedure','copy arbitrary binaries or rerun the update blindly'],['Connections fail after update','SQLCODE, database upgrade state, db2diag, client/server levels','database upgrade omitted or incompatible client/runtime','rehearse and execute a separately approved upgrade if required','run UPGRADE DATABASE reactively']],lab:'On disposable systems, update a clone, capture levels, update one instance, test clients and backup/restore, then exercise the documented rollback. No Db2 lab is available; NOT YET EXECUTED.',q:'Why are a fix pack and database upgrade separate checklist items?',a:'They change different state: installer binaries versus database structures and compatibility. Their prerequisites and rollback paths differ.',diagram:'flowchart TD\nI[Inventory] --> P[Fix-pack prerequisites]\nP --> B[Update binaries]\nB --> V[Verify level and services]\nV --> U{Database upgrade needed?}\nU -->|Yes| R[Readiness, backup, clone rehearsal]\nR --> D[Explicit database upgrade]',refs:[R.fixpack,R.upgrade,R.ready],related:['A-05','B-02','F-03','G-01','K-03']}),
M({id:'I-02',title:'Database upgrade readiness and validation',scope:['source/target compatibility','readiness verification','blocker resolution','database upgrade execution','packages and application behavior','recovery boundary'],branches:[['In-place upgrade','Use only on a supported path with outage and recovery plan.','Restoring old binaries may not reverse upgraded database state.'],['Migration','Build a separate target when isolation or platform move requires it.','Requires complete data, object, and security reconciliation.'],['Defer','Resolve blockers or remain on a supported source level.','Do not suppress readiness findings to force the change.']],steps:['Confirm supported source/target versions, platform, and topology.','Run readiness checks on representative clone and inspect all findings.','Resolve invalid objects, capacity, log, and package issues.','Take and verify recovery copy; define no-return and rollback decision.','Upgrade clone; compare workload and validate application paths.','Execute approved sequence and verify objects, backup, restore, and HA.'],pre:['Capture exact source fix pack, OS, topology, codeset, registry, and configuration.','Check all databases/partitions and retain full readiness output.','Test client, driver, routine, utility, and critical SQL compatibility.'],commands:[['Readiness check','db2ckupgrade SAMPLE -l /db2upgrade/readiness.log','Instance owner','Representative clone SAMPLE','Use target-version tool path and documented database-state prerequisites.','Readiness log lists checked objects and findings.','Review the complete log; prove every database and partition was examined.','Read-only; a pass does not prove application compatibility.'],['Approved upgrade','db2 UPGRADE DATABASE SAMPLE','Instance owner with required authority','Clone first; approved production target second','Verified backup/recovery path, supported path, stopped application traffic, capacity, and change approval.','Upgrade completes and supported connections succeed.','Inspect db2diag, object/package validity, critical SQL, backup, and restore.','Preserve evidence and follow documented recovery; do not rerun blindly or assume binary rollback is database rollback.']],example:'A readiness log flags an invalid routine and low log headroom. Resolve and rehearse both issues on the clone before scheduling the production change.',expected:'Evidence includes readiness findings, rehearsal timing, upgrade result, critical app checks, new backup, restore proof, and recovery decision.',issues:[['Upgrade stops on a blocker','readiness log, SQLCODE, db2diag, object state, disk and log capacity','unsupported object/path or unmet prerequisite','preserve diagnostics, restore rehearsal, resolve cause, and retry on clone','repeat in-place attempts on the only recoverable copy'],['Database opens but one app regresses','package validity, driver, explain plan, SQL errors, transaction results','invalidated package or changed compatibility/optimizer behavior','scope rebind or compatibility changes after representative testing','change multiple registry/config values together']],lab:'Upgrade a disposable copy on a supported source-target path, address readiness warnings, verify objects and packages, compare workload, and test restore. No Db2 lab; NOT YET EXECUTED.',q:'What proves success beyond UPGRADE DATABASE returning successfully?',a:'Critical transactions/utilities work, objects and packages are valid, performance meets thresholds, HA and backup/restore work, and recovery limits are understood.',diagram:'flowchart LR\nS[Source inventory] --> C[Compatibility/readiness]\nC --> F[Resolve blockers]\nF --> R[Clone and recovery rehearsal]\nR --> U[Upgrade]\nU --> V[Objects, apps, backup, restore]',refs:[R.ready,R.upgrade,R.restr],related:['I-01','C-07','F-03','G-01','K-03']}),
M({id:'I-03',title:'Migration and platform moves',scope:['physical image portability','redirected restore mapping','logical movement tools','schema/security/identity completeness','cutover and delta capture','transaction reconciliation'],branches:[['Backup/restore','Use when exact OS, hardware, and release path is supported.','Do not infer portability from equal version numbers.'],['Logical movement','Use export/import/load/db2move for unsupported image paths or selective scope.','Recreate behavior-bearing DDL, grants, and identity state.'],['Staged replication','Use only with product support, licensing, and cutover/reconciliation design.','Define lag, conflict, and final sync decision.']],steps:['Set platform, scope, outage, codeset, RPO, and rollback target.','Check official portability and release compatibility.','Inventory DDL, grants, routines, sequence/identity state, special types, and dependencies.','Move representative objects/data and compare behavior.','Freeze writes or capture final deltas; validate and cut over.','Keep source recoverable/read-only through the reconciliation window.'],pre:['Record source/target Db2 level, OS, architecture, codeset, page size, and topology.','Plan keys, external routines, replication/federation, temporary space, and transfer capacity.','Define row, constraint, identity, grant, and app transaction reconciliation.'],commands:[['Capture source definition','db2look -d SRCDB -e -a -l -x -o /migration/srcdb.sql','Migration DBA','Source catalog and object definitions','Protect output; it may contain identifiers or sensitive definitions.','DDL, object, and grant output is written for review.','Compare with catalog object inventory and separately protected security inventory.','Read-only; secure and expire files by policy.'],['Bounded export example','db2 export to /migration/sample.del of del select CUSTOMER_ID, STATUS from APP.CUSTOMER where CUSTOMER_ID between 1 and 1000','Source read-authorized user','Synthetic/bounded source rows','Specify code page, delimiter, LOB/XML behavior, stable key range, and protected destination.','Selected rows are exported with utility messages.','Compare count and deterministic aggregates with the source query.','Read-only source; treat staged rows as sensitive.']],example:'Before moving Linux data to AIX, check official image portability. If physical restore is unsupported, plan logical movement and recreate grants, sequences, triggers, and external routines deliberately.',expected:'Migration design documents supported method, object/security completeness, delta/cutover plan, reconciliation limits, and rollback criteria.',issues:[['Target rejects physical image','image header, OS/architecture, release, codeset, and restore message','cross-platform path unsupported','use a supported conversion or choose logical movement','modify backup headers or retry unsupported restore'],['Counts match but behavior differs','constraints, identity values, grants, routines, triggers, code page, and app transactions','logical migration omitted behavior-bearing objects','reconcile metadata and test boundary inserts/updates with application owner','declare completion from counts only']],lab:'Move a synthetic schema between disposable databases using documented physical and logical options where supported; compare objects, grants, rows, identities, and app behavior. No Db2 lab; NOT YET EXECUTED.',q:'Why are row counts insufficient for migration sign-off?',a:'They do not prove constraints, routines, triggers, privileges, generated identities, encodings, or application behavior moved correctly.',diagram:'flowchart TD\nO[Platform and downtime goals] --> M{Supported method?}\nM --> B[Backup/restore]\nM --> L[DDL plus logical data movement]\nM --> R[Staged replication]\nB --> V[Objects/security/data behavior]\nL --> V\nR --> V\nV --> C[Cutover and rollback gate]',refs:[R.cross,R.backup,R.restore,R.export,R.load,R.move],related:['C-03','C-05','F-03','G-04','K-04']}),
M({id:'I-04',title:'Federation and remote data access',scope:['wrapper/server/user mapping/nickname','remote credentials and least privilege','pushdown and remote plan','network/TLS and remote failure','remote source support','federation versus local copy'],branches:[['Federated read','Query supported remote source through wrapper and nickname.','Remote latency and estimates affect local work.'],['Write-through','Use only for documented operations and tested transaction behavior.','Do not assume all sources share Db2 semantics.'],['Local copy/replication','Choose for bounded latency, availability, or historical snapshots.','Adds freshness and reconciliation duties.']],steps:['Confirm source wrapper and supported release.','Create least-privilege remote identity and protected mapping.','Register server, test connection, define nickname and statistics.','Explain query and verify predicate pushdown and remote plan.','Monitor remote latency/errors and define fallback/timeout.','Reassess against local replication or ETL needs.'],pre:['Verify feature entitlement and wrapper support.','Keep password out of scripts, command history, logs, and examples.','Agree TLS, endpoint, timeout, remote account, and data classification.'],commands:[['Inventory server/nickname','SELECT servername, wrappername FROM syscat.servers; SELECT nickname, remote_schema, remote_table FROM syscat.nicknames','Catalog reader','Federation catalog','Confirm catalog columns and privileges on installed fix pack; mask sensitive endpoint options.','Registered server and nickname names are listed.','Compare with source owner and test mapped-user connectivity.','Read-only.'],['Explain nickname query','EXPLAIN PLAN FOR SELECT CUSTOMER_ID FROM APP.REMOTE_CUSTOMER WHERE CUSTOMER_ID = 42','Query owner','Read-only nickname query','Use supported explain setup and remote explain privileges.','Plan is recorded if the wrapper supports explain.','Inspect remote SQL/predicate pushdown and source-side plan.','Read-only; clear only owned explain rows through approved housekeeping.']],example:'If a nickname query is slow while local health is normal, check pushdown, remote statistics, network time, and source plan before increasing local memory.',expected:'Federated access has supported wrapper, protected identity, bounded workload, measured pushdown, timeout behavior, owner, and fallback decision.',issues:[['Remote connection timeout','SQLCODE/SQLSTATE, db2diag, masked options, network/TLS and source logs','DNS, firewall, TLS, mapping, remote outage, or timeout mismatch','test each boundary as mapped identity; bound retry behavior','put passwords in ad hoc DDL or loop retries'],['Large remote scan','explain output, remote SQL, nickname statistics, rows transferred, source plan','predicate not pushed or statistics/type mismatch','adjust supported query shape and refresh stats, then verify source plan','assume local estimates prove remote cost']],lab:'On two disposable databases, create read-only mapping and nickname, compare pushed query with non-pushed query, simulate outage, then remove isolated objects. No federation lab; NOT YET EXECUTED.',q:'When should data be copied locally instead of queried remotely?',a:'When latency, availability, remote load, freshness, or transaction requirements cannot be met by federation.',diagram:'flowchart LR\nA[Application SQL] --> O[Local optimizer/nickname]\nO --> W[Wrapper and identity]\nW --> N[Network/TLS]\nN --> R[Remote plan/data]\nO --> X[Local join and sort]',refs:[R.monitor,R.tls],related:['B-01','D-04','E-03','H-01','K-04']}),
M({id:'I-05',title:'License, feature, and support-boundary inventory',scope:['install and license inventory','edition and feature use','topology-specific rights','current support lifecycle','third-party/add-on products','audit evidence and owner'],branches:[['Installed binaries','Show what is present on the host/copy.','Presence does not prove entitlement.'],['Registered license','Show Db2 registration output.','Reconcile against contract and deployment rights.'],['Feature in use','Join configuration, topology, and workload evidence.','Some components have separate license/support terms.']],steps:['Inventory copies, hosts, editions, and add-ons.','Map workload/topology/features to contract evidence.','Check current support lifecycle and platform matrix.','Record evidence source/date, owner, and unresolved interpretation.','Review before upgrade, migration, or architecture expansion.'],pre:['Use approved procurement/entitlement records, not package names alone.','Check live IBM lifecycle pages because support dates can change.','Separate Db2 core entitlements from separately licensed replication products.'],commands:[['Installed product/license output','db2ls; db2licm -l','Instance owner / license administrator','Each install copy','Run on every host/copy and preserve dated output.','Installed products and registered license data are displayed.','Reconcile product ID/edition and deployment count with contract records.','Read-only.'],['Feature/topology evidence','db2 get dbm cfg; db2 get db cfg for SAMPLE; db2instance -list','Instance owner','All instances/databases and pureScale cluster if used','Collect on all relevant members; redact endpoints/identifiers.','Configuration and topology clues are captured.','Compare with feature usage, entitlement documents, and current support matrix.','Read-only; config is not legal entitlement proof.']],example:'A registered license is technical evidence. A separate contract and feature-use review establishes whether deployment rights cover hosts and topology.',expected:'Dated inventory names product/copy/host, registered license, feature, topology, entitlement source, support status, owner, and open questions.',issues:[['Feature use has no clear entitlement','license output, topology/configuration, workload, and contract evidence','install inventory was not reconciled with commercial rights','ask procurement/IBM to interpret terms and hold new deployment pending review','infer non-use from a disabled-looking parameter'],['Target platform support is uncertain','source/target level, OS, topology, and current lifecycle page','support matrix or dates changed','validate the current official matrix and attach dated evidence','reuse an undated compatibility spreadsheet']],lab:'Create a mock three-host inventory and reconcile technical outputs with fictional contracts; identify unknowns and route them to owner. Live entitlement review is NOT YET EXECUTED.',q:'What does db2licm -l establish?',a:'It shows license registration reported by that installation. It does not interpret contract terms or prove every feature deployment is entitled.',diagram:'flowchart TD\nB[Copy and binary inventory] --> L[Registered license]\nT[Feature/topology evidence] --> E[Entitlement record]\nS[Current support lifecycle] --> D[Deployment decision]\nL --> D\nE --> D\nT --> D',refs:[R.auth],related:['B-02','B-06','I-01','I-04','G-04']}),
M({id:'I-06',title:'Change control, rollback, and post-change proof',scope:['blast radius and accountable owner','pre/post-state evidence','measurable go/no-go gate','configuration versus data rollback','canary and observation window','handoff and closure'],branches:[['Reversible parameter','Save old value and exact reverse action.','Activation may require reconnect or restart.'],['Data/format mutation','Require tested recovery image and restore route.','Rollback may mean restore, not inverse SQL.'],['Role/topology change','Require fencing, routing, and ownership plan.','A second writer can corrupt service.']],steps:['State desired user outcome, scope, and owner.','Capture state, dependencies, health, and recovery point.','Define thresholds, stop/go checks, and measurable rollback triggers.','Apply smallest scoped step and pause at gates.','Verify independently and observe representative workload.','Record result, evidence, and handoff.'],pre:['Confirm authority, window, on-call contacts, and application owner.','Validate exact target and correct instance/role.','Make rollback materials available outside the affected component.'],commands:[['Capture baseline','db2 get dbm cfg; db2 get db cfg for SAMPLE; db2pd -db SAMPLE -alldbs','Instance owner','Selected instance and database','Read-only; save time, target, and change ID in restricted location.','Current configuration and engine status are captured.','Compare after change and validate app transactions independently.','Read-only.'],['Illustrative configuration change','db2 update db cfg for SAMPLE using LOCKTIMEOUT 30','Instance owner with approval','SAMPLE database','Example only: verify value, activation, app retry behavior, workload and prior value first.','Db2 accepts the parameter; activation can vary by parameter.','Requery effective setting and test bounded app transactions/lock metrics.','Restore recorded value through approved change; reversal cannot undo workload side effects.']],example:'A shorter lock timeout can release blocked work sooner but increase application errors. Measure both queue duration and retry/error behavior.',expected:'Record contains baseline, target, authority, accepted output, effective-state proof, business outcome, trigger result, owner, and rollback boundary.',issues:[['Accepted setting but no behavior change','target scope, effective parameter, activation type, member, app telemetry','wrong target or deferred activation','confirm scope and apply activation through approved window','repeat across every database without checking scope'],['Reverted setting but issue remains','timeline, other changes, app retries, utility state, data side effects','not all consequences are reversible or there were multiple causes','stabilize and inspect dependent state; use recovery plan for data effects','assume old config restores old service state']],lab:'Write and tabletop a benign parameter change with baseline, app thresholds, activation, rollback value, and adverse result branch. No live mutation; NOT YET EXECUTED.',q:'What makes a rollback trigger useful?',a:'It is measurable and tied to service/data outcome, has a time window, and names the decision owner and recovery action.',diagram:'flowchart TD\nR[Outcome and blast radius] --> B[Baseline and recovery boundary]\nB --> G[Go/no-go checks]\nG --> A[Scoped action]\nA --> V[Independent verification]\nV --> Q{Threshold met?}\nQ -->|Yes| O[Observe and hand off]\nQ -->|No| X[Stop and recover]',refs:[R.backup,R.diag],related:['A-04','E-06','F-03','I-01','K-03']}),

M({id:'J-01',title:'Safe DBA automation and idempotency',scope:['target allowlist and environment','idempotent state check','service identity and secret handling','timeout/retry/locking','logging and status','partial-failure recovery'],branches:[['Read-only discovery','Automate inventory and evidence first.','Validate output, overhead, and alerts.'],['Idempotent action','Repeat only when desired-state check is explicit.','Utility completion may be asynchronous.'],['Non-idempotent action','Require ticket, approval, and unique run ID.','Never blindly retry an ambiguous backup/restore/action.']],steps:['Define target and precondition contract.','Pin copy/profile and use restricted service account.','Check desired state and skip safe no-op.','Apply bounded action with timeout, lock, and useful status.','Verify independent post-state.','Test duplicate, interrupted, and partial runs.'],pre:['Pin DB2INSTANCE, Db2 copy, host, database, timezone, and path.','Use approved secret manager; never put credentials in args or logs.','Define concurrency, retry limits, and owner.'],commands:[['Read-only probe','#!/usr/bin/env bash\nset -euo pipefail\nexport DB2INSTANCE=db2inst1\n. ~db2inst1/sqllib/db2profile\ndb2 connect to SAMPLE\ndb2pd -db SAMPLE -alldbs','Scheduled service identity','Allowlisted SAMPLE on one host','Pin environment, profile, Db2 level, output path, and access rights.','Health evidence or nonzero failure status is returned.','Log time, target, level, command status, and connection identity; test notification fields.','Read-only apart from connection state.'],['Per-target lock','flock -n /var/lock/db2-sample.lock timeout 1800 /opt/dbatools/check_sample.sh','Automation account','One maintenance invocation','Lock directory is restricted; script handles timeout and signals.','Only one invocation proceeds; overlapping run is visible.','Test concurrent runs and lock release on success, failure, and termination.','Terminate only the automation process after checking Db2 utility state.']],example:'A scheduler loses its SSH response after a backup. The next run checks utility history and target state before retrying; a connection failure is not proof that the operation failed.',expected:'Automation has owner, pinned environment, allowlisted target, explicit state check, collision handling, bounded retry, auditable evidence, and recovery path.',issues:[['Scheduled command differs from interactive','PATH, profile, DB2INSTANCE, copy, locale, user, and working directory','scheduler environment differs','pin/log environment and assert expected target and code level','depend on a user shell profile'],['Outcome ambiguous after connection loss','run ID, utility status/history, target state, scheduler timeout','server completed but acknowledgement was lost','inspect post-state before deciding on retry','automatically repeat non-idempotent operations']],lab:'Build read-only inventory automation with allowlist, profile assertion, timeout, redaction, lock, and failure injection. No Db2 runtime; NOT YET EXECUTED.',q:'Why is idempotency more than enabling retries?',a:'Safe repetition requires checking the desired state. A blind retry can duplicate or damage non-idempotent work.',diagram:'flowchart TD\nT[Allowlisted target/run ID] --> P[Profile and prerequisites]\nP --> S{Already in desired state?}\nS -->|Yes| N[Record no-op]\nS -->|No| L[Lock and bounded action]\nL --> V[Independent post-check]\nV --> E[Audit result]',refs:[R.diag,R.monitor],related:['A-03','A-04','E-06','J-02','K-03']}),
M({id:'J-02',title:'Scheduling, alerts, and runbook routing',scope:['signal source and scope','threshold/baseline/SLO','freshness and collection gaps','deduplication and escalation','runbook linkage','alert tests and retirement'],branches:[['Threshold','Use known safety boundary with a duration.','Static thresholds may page during normal peaks.'],['Anomaly','Use deviation from seasonal baseline.','Keep explanation and false-positive burden visible.'],['SLO symptom','Alert on user transaction latency/errors.','Pair with component evidence for diagnosis.']],steps:['Name service symptom and impact window.','Choose authoritative signal, dimensions, and freshness limit.','Set threshold, duration, grouping, suppression, and owner.','Link first response and evidence capture.','Test fire, dedup, silence, escalation, and recovery.','Review alert usefulness and retire stale rules.'],pre:['Synchronize clocks across Db2, OS, scheduler, and application.','Protect event data and payloads; avoid sensitive SQL literals.','Bound monitoring overhead and event-monitor storage.'],commands:[['Monitor counters','SELECT CURRENT TIMESTAMP, MEMBER, TOTAL_APP_COMMITS, TOTAL_APP_ROLLBACKS FROM TABLE(MON_GET_DATABASE(-2)) AS M','Monitoring identity','Database aggregate by active member','Verify function signature and privileges on installed release.','Timestamped counters are returned.','Compare deltas over equal intervals with app request telemetry.','Read-only; avoid high-frequency polling.'],['Bounded diagnostic tail','tail -n 80 $HOME/sqllib/db2dump/db2diag.log','Instance owner/log collector','Selected diagnostic file','Protect access and redact before sharing.','Recent diagnostic entries are read.','Correlate timestamp, member, severity, SQLCODE, and alert ID.','Read-only; retain required support evidence.']],example:'Page only after sustained CPU saturation and transaction latency/error impact. A one-sample CPU threshold without service context creates noise.',expected:'Each alert has purpose, signal, scope, threshold/window, freshness, dedup key, owner, runbook, and recovery test.',issues:[['Repeated pages for one incident','fingerprint, windows, suppression, source gaps, and incident link','no grouping/hysteresis or unstable dimensions','deduplicate by service/target and test clear threshold','silence all alerts for the service'],['Green dashboard during outage','signal freshness, query errors, collection gap, user transaction telemetry','signal does not represent impact or collector is stale','monitor SLO symptom and collector freshness','trust a green panel without data age']],lab:'Simulate log space, HADR state, connection errors, and latency; test dedup, silence, recovery, and runbook links. No monitoring platform connected; NOT YET EXECUTED.',q:'What makes an alert actionable?',a:'It identifies target and impact, includes fresh evidence, reaches a named owner, and links a safe first response.',diagram:'flowchart LR\nS[Db2/OS/app signals] --> C[Collector freshness]\nC --> A[Threshold/anomaly/SLO]\nA --> G[Dedup and maintenance gate]\nG --> P[Owner page/runbook]\nP --> V[Evidence and recovery notice]',refs:[R.monitor,R.mon,R.diag],related:['E-02','E-03','E-06','J-01','K-03']}),
M({id:'J-03',title:'Backup automation, retention, and restore proof',scope:['backup target and role gate','image/history/log chain','offsite copy and integrity','encryption key recovery','dependency-aware retention','isolated restore test'],branches:[['Scheduled backup','Use bounded storage and concurrency policy.','Success is not restore proof.'],['Log archive','Protect ordered logs and retrieval method.','Retention determines recoverable point.'],['Retention cleanup','Delete only after dependency/legal checks.','Age alone is not safe eligibility.']],steps:['Set RPO/RTO and protected-copy requirement.','Take image and needed logs to approved destination.','Record image identity/history/checksum/key metadata.','Transfer and verify independent copy.','Restore to isolation and measure recovery.','Apply dependency-aware retention and watch evidence age.'],pre:['Confirm capacity, permissions, encryption key escrow, and transfer path.','Check database role, active utilities, and schedule overlap.','Retain dependent full/incremental images and ordered logs.'],commands:[['Online backup example','db2 backup database SAMPLE online to /db2backup/SAMPLE include logs compress','Backup service identity','Approved SAMPLE role and target','Check archive logging, free space, role, path, utility overlap, and CPU impact.','Backup image and included logs are produced if command completes.','Check history, image header, remote checksum, key availability, and restore test.','Do not delete existing images after failure; inspect partial output and retain logs.'],['History inventory','db2 list history backup all for SAMPLE','Instance owner/auditor','SAMPLE history','Use correct instance; history does not prove external copy readability.','Backup entries show timestamp, type, and location.','Reconcile with object store, checksum, key, and restore-test evidence.','Read-only.']],example:'A local backup succeeds but offsite copy transfer fails. Site-loss RPO is not met; independently monitor remote-copy and restore-test freshness.',expected:'Evidence proves correct image, chain/log/key availability, protected independent copy, dependency-aware retention, and recent usable restore.',issues:[['Successful backup will not restore','image header/checksum, history, object version, key, log chain, restore diagnostics','truncated copy, lost key/log, wrong chain, or unsupported target','use known-good copy and correct transfer/retention failure','delete prior image before replacement restore passes'],['Cleanup removes needed base/log','incremental dependency, archive chain, recovery point and delete job','age-based cleanup ignored recovery dependencies','restore dependency-aware retention and re-evaluate recoverable point','wildcard delete by age']],lab:'Automate synthetic backup, integrity/remote copy check, isolated restore, query, and evidence; inject storage and missing-key failure. No Db2 lab; NOT YET EXECUTED.',q:'What does a backup success record need to prove?',a:'Correct image, available logs and keys, independent protected copy, and a recent isolated restore with usable data.',diagram:'flowchart TD\nS[Role gate and schedule] --> B[Backup plus logs]\nB --> H[Image identity/history]\nH --> T[Transfer/checksum/key]\nT --> R[Isolated restore]\nR --> E[RPO/RTO evidence]',refs:[R.backup,R.restore,R.recover,R.roll],related:['F-03','F-04','F-05','F-09','J-01','K-02']}),
M({id:'J-04',title:'Configuration as code, secrets, and drift',scope:['desired configuration source','secret versus nonsecret values','version and environment scope','drift review','activation semantics','scoped apply and rollback'],branches:[['Tracked parameter','Version desired value, owner, and reason.','Check scope and activation.'],['Secret','Store a reference and access policy.','Never version secret values.'],['Observed drift','Compare read-only and investigate owner.','Do not auto-correct unknown production state.']],steps:['Inventory parameters, registry values, profiles, certs, and users.','Classify secret/sensitive/environment-specific values.','Store safe desired state with review and exception process.','Detect drift and identify reason/owner.','Apply scoped change through approval and verify effective value.'],pre:['Remove passwords, tokens, private keys, and customer identifiers.','Do not version unrestricted database config dumps.','Pin release-specific names and accepted values.'],commands:[['Capture protected snapshot','db2 get db cfg for SAMPLE','Instance owner/configuration manager','One named database','Restrict output; record exact release, host, instance, and timestamp.','Current configuration prints to terminal.','Compare only reviewed keys to desired state; check activation semantics.','Read-only; redact and retain under policy.'],['Illustrative setting','db2 update db cfg for SAMPLE using AUTO_MAINT ON','Instance owner','SAMPLE database','Example only: confirm current value, maintenance window, release, and scheduled behavior.','Db2 accepts the setting.','Requery effective value and inspect maintenance configuration/status.','Restore prior value via reviewed change; stop dependent schedule separately if needed.']],example:'Track desired maintenance settings and owner in version control; inject endpoints and secret references at deploy time. Drift opens review rather than overwriting a possible emergency change.',expected:'Config has owner, scope, release, activation, test, approval, rollback, secret exclusion, and measured drift.',issues:[['Instances differ after rollout','copy/profile, scope, return code, activation, member snapshots','wrong target or deferred parameter','pin environment and verify every instance/member','assume one command changed all targets'],['Secret appears in artifact','scanner, Git history, build logs, shell history, backups','secret was passed as argument or rendered to output','revoke/rotate, restrict exposure, purge according to policy, move to secret reference','delete only latest file while history remains']],lab:'Use a mock baseline and fake secret reference. Review drift, approve one safe change, scan outputs, and roll back. No live change; NOT YET EXECUTED.',q:'Why should drift detection avoid automatic repair by default?',a:'Observed drift may be an intentional emergency or recovery state. Identify its owner and impact before applying stale desired state.',diagram:'flowchart LR\nD[Desired configuration] --> C[Read-only comparison]\nO[Observed database state] --> C\nC --> Q{Approved exception?}\nQ -->|Yes| R[Record exception]\nQ -->|No| H[Owner/change review]\nH --> A[Scoped apply and verify]',refs:[R.auth,R.tls,R.encryption],related:['D-01','D-02','I-06','J-01','K-03']}),
M({id:'J-05',title:'Runbooks, handoffs, and incident records',scope:['trigger and impact','target identity and role','timeline and evidence','branch and stop rule','named owner and next action','review/expiry'],branches:[['Routine task','Show prerequisites, action, check, and cleanup.','Distinguish destructive branches.'],['Incident','Preserve evidence and verify impact first.','Avoid unverified fixes and irreversible shortcuts.'],['Handoff','State current condition, next action, owner, and deadline.','Require acknowledgement.']],steps:['State trigger, severity, target, and impact.','List exact identity checks and read-only evidence.','Separate branches by state and show stop boundary.','Provide authority, prerequisites, expected result, and independent check.','Record rollback limits, escalation, evidence location, and owner.','Peer exercise, update after incident, and set review date.'],pre:['Use fictional/redacted examples, never secrets or customer data.','Name release, OS, topology, role, and authority.','Keep official references current and link directly.'],commands:[['Incident snapshot','date -Is; hostname -f; db2level; db2pd -db SAMPLE -alldbs','Incident evidence lead','Named host and database','Record timezone and incident ID; confirm target/role and data handling.','Timestamp, level, and engine evidence are captured.','Correlate with app, OS/storage, HADR, and change timeline.','Read-only; preserve original evidence.'],['Handoff template','printf "Incident: INC-123\\nTarget: host1/db2inst1/SAMPLE\\nState: recovery pending; traffic stopped\\nNext: verify image chain\\nOwner: DBA on call\\nDecision by: 12:00 UTC\\n"','Incident commander','Approved ticket or handoff system','Illustrative fictional values only; use secure ticket template.','Receiver gets state and bounded next action.','Obtain acknowledgement and confirm evidence access.','Correct access promptly if handoff reached wrong recipient.']],example:'For a recovery-pending handoff, include host/instance/alias, current status, last message, missing log, traffic state, evidence path, safe next check, owner, and decision deadline.',expected:'A peer can confirm target, reproduce evidence, choose next supported branch, and understand point of no return without oral context.',issues:[['Conflicting recovery actions','timeline, ticket owner, utility state, and command audit','no single decision owner or durable handoff','pause duplicate mutation, name commander/action owner, inspect current state','assume chat history is a runbook'],['Command targets wrong database','hostname, DB2INSTANCE, directory, connection identity, runbook version','placeholder or stale environment copy','require explicit target confirmation and retire stale copy','copy production endpoints into generic notes']],lab:'Peer-read a read-only incident runbook with wrong-host, restore-pending, and missing-log branches. Peer exercise not done here; NOT YET EXECUTED.',q:'What is the minimum useful handoff?',a:'Target/environment, impact, verified state, timeline/last action, evidence, safe next step, owner, escalation, and deadline.',diagram:'flowchart TD\nT[Trigger/impact] --> I[Identify target]\nI --> E[Preserve evidence]\nE --> B[Select branch and stop rule]\nB --> A[Named action owner]\nA --> H[Verify and hand off]',refs:[R.diag,R.monitor],related:['E-06','F-07','I-06','J-02','K-01']}),
M({id:'J-06',title:'Service objectives, capacity trends, and improvement',scope:['transaction SLO','RPO/RTO and dependencies','latency/error/throughput baseline','capacity headroom and skew','trend uncertainty','measured improvement'],branches:[['SLO symptom','Measure user transaction success and latency.','Engine uptime is not user availability.'],['Recovery objective','Measure restore/failover end-to-end.','A written target is not tested evidence.'],['Capacity','Trend demand and saturation by resource/member.','Averages hide peaks and skew.']],steps:['Define critical transaction and service window.','Map app, network, Db2, storage, backup, and recovery dependencies.','Collect aligned time-series with units, member scope, and freshness.','Calculate availability, growth, capacity, RPO/RTO, and uncertainty.','Exercise recovery/capacity and compare with target.','Assign and retest prioritized improvement.'],pre:['Align clocks and sampling across application, Db2, OS, storage, and HA.','Separate planned maintenance from unexpected outage.','Include batch, peak, and per-member workload.'],commands:[['Member counters','SELECT CURRENT TIMESTAMP, MEMBER, TOTAL_APP_COMMITS, TOTAL_APP_ROLLBACKS FROM TABLE(MON_GET_DATABASE(-2)) AS M','Monitoring identity','Database members','Verify function signature; sample at agreed interval.','Timestamped cumulative counters appear per member.','Compute interval deltas and compare with application requests.','Read-only; a cumulative counter is not a rate.'],['Filesystem headroom','df -h /db2data /db2log /db2archive; df -i /db2data /db2log /db2archive','Linux host operator','Actual data/log/archive mount points','Map Db2 containers/archive path; check quotas/object storage separately.','Capacity and inode usage are shown.','Compare trend, reserve threshold, tablespace/log state, and growth forecast.','Read-only.']],example:'A 99.9% availability goal is meaningless until eligible transactions, partial service, maintenance, and measurement window are agreed.',expected:'Service review shows transaction availability/latency, measured recovery, capacity forecast assumptions, data freshness, and prioritized owner/date.',issues:[['Healthy average but bad peak experience','percentiles, per-member skew, batch windows, sample count, and errors','aggregation masks tail latency or missing data','segment by transaction, member, and time; show sample freshness','report only average CPU or uptime'],['RTO missed','restore/failover timeline, volume, log replay, key retrieval, validation and cutover','target omitted real dependencies or was never tested','measure full service path, remove bottleneck, and retest','skip validation to meet the clock']],lab:'Use synthetic metrics to calculate availability, p95 latency, error budget, measured RTO/RPO, and growth; identify missing dimensions. No operational telemetry; NOT YET EXECUTED.',q:'Why does service RTO extend beyond database recovery?',a:'Application readiness, routing, authentication, dependent services, validation, and business reconciliation must also finish.',diagram:'flowchart LR\nU[User transactions] --> S[SLO: availability/latency/errors]\nS --> D[Db2 and dependency signals]\nD --> C[Capacity and skew]\nC --> R[Measured recovery]\nR --> P[Improvement and retest]',refs:[R.monitor,R.mon,R.hadr,R.backup,R.restore],related:['A-01','E-02','F-03','G-01','J-02']}),

M({id:'K-01',title:'Senior incident command and evidence-based action',scope:['impact/severity','single incident commander','cross-layer evidence timeline','hypothesis testing','safe mitigation','business verification'],branches:[['Service degraded','Preserve evidence and use a known bounded mitigation.','Do not tune before identifying the bottleneck.'],['Integrity risk','Fence unsafe writes and protect recovery artifacts.','Preventing further corruption outranks rapid service restoration.'],['Engine/host failure','Coordinate Db2, OS, network, and storage evidence.','Avoid restarts that destroy diagnostics.']],steps:['Declare impact, severity, window, and commander.','Confirm host/instance/database/role and freeze unrelated change.','Capture aligned application, OS, Db2, storage, and diagnostic evidence.','List hypotheses and evidence that distinguishes them.','Choose least-risk action with owner, stop rule, and data-loss decision.','Verify user transaction and data correctness; preserve timeline.'],pre:['Use out-of-band comms if database/network is impaired.','Confirm primary/standby and fencing before role/routing changes.','Preserve diagnostics under secure support policy.'],commands:[['Bounded incident snapshot','date -Is; hostname -f; db2level; db2pd -inst; db2pd -db SAMPLE -alldbs; tail -n 120 $HOME/sqllib/db2dump/db2diag.log','Evidence lead / instance owner','Named host and SAMPLE database','Check role, timezone, file path, access, and incident ID.','Bounded timestamped engine and diagnostic evidence is captured.','Correlate with app request IDs, OS/storage, HADR, and exact failure window.','Read-only; preserve originals.'],['Compare HADR endpoints','db2pd -db SAMPLE -hadr; db2pd -db SAMPLE -transactions','HADR operator','Both reachable HADR hosts','Collect both sides; fence write ownership before takeover/routing.','Role/state and transaction evidence are returned when reachable.','Compare role, log positions, peer state, routing, and cluster controls.','Read-only; do not promote from one node output.']],example:'Slow commits and connection spikes arrive together. Capture timeline and role, then distinguish lock waits from storage latency before considering restart or parameter change.',expected:'Incident record connects user impact to evidence, controlled action, explicit data-loss decision if needed, and verified service recovery.',issues:[['Several changes precede diagnosis','change timeline, config deltas, utility states, missing baseline','no commander or hypothesis under pressure','pause, assign owners, capture state, test one reversible hypothesis','change memory, routing, and role simultaneously'],['Engine online but data unsafe','integrity query, role/fencing, transaction reconciliation, app smoke test','health check stopped at process status','keep writes fenced until role/data/app path are verified','close incident from process status alone']],lab:'Tabletop log pressure plus lock storm, followed by network split with HADR. Rotate commander/evidence/app/action roles. No live drill; NOT YET EXECUTED.',q:'What makes a senior response more than a command checklist?',a:'It coordinates impact, evidence, hypotheses, owners, recovery options, and business verification rather than equating command success with resolution.',diagram:'flowchart TD\nI[Impact and commander] --> T[Confirm target/role]\nT --> E[Cross-layer evidence]\nE --> H[Hypotheses and checks]\nH --> A[Bounded action]\nA --> V[Data and user verification]\nV --> R[Timeline and learning]',refs:[R.diag,R.monitor,R.hadr],related:['E-06','F-07','G-01','G-02','J-05','K-02']}),
M({id:'K-02',title:'Capstone: database loss and business reconciliation',scope:['incident and recovery endpoint','image/log/key chain','isolated restore','end-log versus point-in-time','RPO/RTO and data loss','application reconciliation and cutover'],branches:[['Media loss, logs intact','Restore known image and roll forward to approved endpoint.','Prove every required log and image.'],['Logical corruption','Choose a point before bad commit with business approval.','Quantify lost valid work.'],['Uncertain state','Recover to isolated target and compare.','Do not overwrite surviving source while uncertain.']],steps:['Classify scope, RPO/RTO, and known-good time.','Locate image, logs, key, and target capacity.','Select isolated target/endpoint with business owner.','Restore and roll forward; capture messages/time.','Validate data/integrity and reconcile post-endpoint transactions.','Fence/reroute on cutover and preserve source/evidence.'],pre:['Verify image identity, checksums, chain, logs, and key.','Convert endpoint to Db2 timestamp with timezone decision.','Include storage, app, security, network, and business owners.'],commands:[['Isolated restore template','RESTORE DATABASE SAMPLE FROM /db2backup TAKEN AT 20261027100000 INTO QA1 NEWLOGPATH /db2log/QA1 REDIRECT WITHOUT ROLLING FORWARD','Recovery authority','Isolated QA1 host/instance','Confirm image, platform, mapping, key, capacity, and distinct alias; use generated redirect script if required.','Image restores into isolated alias, possibly pending logs.','Check utility messages, paths, and rollforward status before client route.','Do not touch source; retain evidence before dropping QA1.'],['Approved endpoint template','ROLLFORWARD DATABASE QA1 TO END OF LOGS OVERFLOW LOG PATH (/db2archive/SAMPLE) AND STOP','Recovery authority with business decision','Isolated QA1 copy','Use only after archive completeness; PIT requires explicit timestamp and timezone.','Logs apply and STOP completes at chosen endpoint.','Run integrity/app checks and record elapsed time, endpoint, and lost transactions.','STOP is terminal; wrong endpoint requires a planned new restore/recovery.']],example:'Latest valid image is 10:00, logs through 10:43, storage lost at 10:45. RTO includes restore, replay, checks, routing, and reconciliation; RPO is measured at last recoverable commit, not backup time alone.',expected:'Recovery record names supported image/log chain, endpoint, business loss approval, isolation, checks, cutover criteria, and measured RPO/RTO.',issues:[['RTO exceeded','image size, throughput, replay, key retrieval, validation, cutover timestamps','plan omitted media or business steps','measure phases and retest representative volume','skip validation to meet time'],['App queue conflicts with restored rows','commit/request IDs, endpoint/timezone, app retry ledger','PIT boundary or queued writes not reconciled','preserve clone and reconcile idempotent requests with app owner','blindly replay queued writes']],lab:'Tabletop with image inventory, log gap, unavailable key, bad-commit timestamp, RPO/RTO and app queue. Select recovery, loss, run sequence and gates. Full restore NOT YET EXECUTED.',q:'Who approves point-in-time data loss?',a:'The accountable business/data owner approves; the DBA supplies verified endpoint and quantified loss, then executes it.',diagram:'flowchart TD\nI[Incident] --> A[Images/logs/keys/capacity]\nA --> D{Known-good endpoint?}\nD -->|latest logs| L[End-of-logs]\nD -->|before bad commit| P[Approved PIT]\nL --> V[Integrity and reconciliation]\nP --> V\nV --> C[Safe cutover]\nC --> M[Measure RPO/RTO]',refs:[R.backup,R.restore,R.roll,R.recover,R.encryption],related:['F-03','F-05','F-07','F-08','J-03','K-01']}),
M({id:'K-03',title:'Capstone: performance incident across SQL, locks, memory, and storage',scope:['transaction impact/change timeline','plan and statistics','lock chain and rollback','memory/temp/log/storage','safe mitigation','representative verification'],branches:[['Regressed SQL','Compare plan, stats, binds, and data distribution.','Do not force an access path without measurement.'],['Blocked workload','Identify blocker and business owner.','Cancel can trigger large rollback.'],['Resource saturation','Correlate Db2 demand with host/storage/network.','Raising limits can move pressure or exhaust host.']],steps:['Identify affected transaction, interval, impact, and recent changes.','Capture plan, runtime, lock, memory/temp/log, host, and storage data.','Distinguish bottleneck from correlated symptoms.','Choose one bounded mitigation with owner and trigger.','Compare latency, throughput, errors, and resources.','Document cause, permanent fix, and guardrail.'],pre:['Freeze unrelated tuning and identify known-good workload.','Redact literals/PII; capture package/section and bind options.','Confirm business impact before canceling/throttling transactions.'],commands:[['Sample active activities','SELECT APPLICATION_HANDLE, MEMBER, ACTIVITY_ID, STMT_TEXT, TOTAL_CPU_TIME, TOTAL_ACT_TIME, ROWS_READ, ROWS_RETURNED FROM TABLE(MON_GET_ACTIVITY(NULL, -2)) AS A','Monitoring/query owner','Active activities by member','Verify signature/columns/privileges; redact SQL literals.','Current activity metrics are returned.','Join to application, transaction, lock, and plan evidence over repeated samples.','Read-only; avoid heavy polling.'],['Inspect lock wait chain','db2pd -db SAMPLE -wlocks -transactions','Instance owner','Current lock and transaction state','Confirm target/member/time; identify business owner before termination.','Lock waits and associated transaction evidence appear.','Trace blocker to unit of work, app, SQL, and business operation.','Read-only; force/cancel requires separate approval.']],example:'Batch doubles after release; broad scan plus stale stats drives CPU and locks. Test statistics or rebind on representative workload before broad production change.',expected:'Root cause identifies workload/evidence; mitigation restores user objective without hidden resource or transaction side effects.',issues:[['Query faster but service throughput worse','concurrency, CPU/I/O queue, locks, transaction rate, competing latency','shared-resource demand or serialization increased','benchmark representative mix and concurrency','use one isolated run as proof'],['Force worsens incident','rollback state, log use, lock chain, retries','large unit of work rolls back while clients retry','stop retry storm and monitor rollback before next action','terminate without estimating rollback/duplicate requests']],lab:'Synthetic workload: baseline plan, create blocker, test one stats/index/mitigation change, compare concurrency, latency and errors. No Db2 lab; NOT YET EXECUTED.',q:'What is sufficient proof that performance is restored?',a:'The affected user transaction meets its objective under representative workload and related error, lock, and resource effects are acceptable.',diagram:'flowchart TD\nI[Symptom and change timeline] --> Q[Plan/stats/runtime]\nQ --> L[Locks/transactions]\nL --> R[Memory/temp/log/storage]\nR --> H[One hypothesis and mitigation]\nH --> V[Latency/errors/concurrency]\nV --> P[Permanent fix/guardrail]',refs:[R.monitor,R.mon,R.diag],related:['C-06','E-02','E-03','E-05','H-01','H-02','H-05','H-06','J-02']}),
M({id:'K-04',title:'Final capstone: recoverable, secure, observable Db2 service',scope:['workload objectives and SLO','topology and independent failure domains','HADR/replication role and client route','logs, backup, encryption, and keys','TLS, authorities, and secrets','monitoring, runbooks, and tested recovery'],branches:[['Single member with HADR','Use when standby and failover meet the service objective.','HADR does not protect from logical corruption.'],['DPF/pureScale','Select only for workload need and operating maturity.','Their member/partition/CF scopes differ.'],['Replication/federation','Select for distribution/integration requirement.','Define lag, consistency, conflict, and licensing.']],steps:['Set transaction SLO, RPO/RTO, data classification, and constraints.','Choose topology and map primary/standby, route, storage, sites, and key access.','Design logs, backup, restore, encryption, TLS, privileges, and secret rotation.','Define monitoring, runbooks, schedule owners, and change gates.','Test site loss, takeover/failback, restore/PIT, key outage, and capacity.','Review evidence, residual risks, support, and next improvement.'],pre:['Name SLO and data-loss decision owner; measurable acceptance is required.','Verify current platform support and feature entitlements.','Check that site, key, network, storage, and power dependencies are independent.'],commands:[['Check HADR endpoints','db2pd -db PROD -hadr; db2 get db cfg for PROD','HADR operator','Both PROD endpoints','Collect from both hosts; verify roles, log positions, peer state, sync mode, and routing. Do not promote from one output.','HADR state and configuration clues are recorded.','Compare architecture, fencing, client path, and measured log gap.','Read-only.'],['Check backup evidence','db2 list history backup all for PROD; db2ckbkp -h /db2backup/PROD.0.db2inst1.DBPART000.20261027100000.001','Backup/recovery operator','History and selected image','Use exact image path and documented checker syntax; protect storage identifiers.','History and image header are displayed if readable.','Compare identity, date, chain, checksum, key, and isolated restore result.','Read-only; do not replace/delete image from header output alone.']],example:'Two HADR VMs share a storage failure domain and a single-site key vault. Network redundancy does not prove site resilience; map dependencies and test key retrieval during DR.',expected:'Review package has objectives, topology/trust boundaries, failover and recovery plans, security, alerts/runbooks, measured drills, and prioritized residual risks.',issues:[['Takeover succeeded but clients fail','role, fencing, DNS/load balancer, TLS trust, credentials, firewall, retries','database role changed but route/trust dependency did not','test full app path and keep old writer fenced','declare DR from takeover output alone'],['Bad data propagated to standby','replication mode/lag, transaction timeline, backup and PIT test','HA confused with independent corruption recovery','keep protected backup and separate PIT drill','use standby as only recovery copy']],lab:'Present architecture and synthetic evidence to DBA, app, security, network/storage, and operations reviewers. Tabletop site loss, key outage, log pressure, and bad transaction. No Db2 cluster; all execution NOT YET EXECUTED.',q:'What proves a Db2 service is recoverable and operable?',a:'Known ownership/topology, independent failure domains, usable security/key paths, actionable alerts, and measured restore/failover drills meeting business targets.',diagram:'flowchart LR\nA[Apps and SLO] --> P[Primary Db2]\nP --> H[HADR standby and fenced route]\nP --> B[Protected backup/log chain]\nP --> M[Monitoring/runbooks]\nS[TLS, keys, authorities] --> P\nB --> R[Isolated restore/PIT drill]\nH --> F[Failover/failback drill]\nR --> O[Operators and evidence]\nF --> O\nM --> O',refs:[R.hadr,R.takeover,R.backup,R.restore,R.roll,R.tls,R.encryption,R.auth,R.monitor],related:['B-06','D-01','D-04','E-06','F-03','F-05','G-01','G-02','G-04','I-05','J-01','J-02','J-03','J-05','K-01','K-02','K-03']})
];
